1const canvas = document.getElementById("gameCanvas");
2const ctx = canvas.getContext("2d");
3let x = 200;
4let y = 150;
5let dx = 2;
6let dy = 1.5;
7function update()  {
8    x += dx;
9    y += dy;
10    if (x < 10 || x > 390) dx = -dx;
11    if (y < 10 || y > 290) dy = -dy;
12}
13function draw()  {
14    ctx.clearRect(0, 0, canvas.width, canvas.height);
15    ctx.beginPath();
16    ctx.arc(x, y, 10, 0, Math.PI * 2);
17    ctx.fill();
18}
19function gameLoop()  {
20    update();
21    draw();
22    requestAnimationFrame(gameLoop);
23}
24gameLoop();
